const buildLang = (idx: number): Record<string, string> => {
  const out: Record<string, string> = {};
  for (const [k, tuple] of Object.entries(PART_B_DATA)) {
    out[k] = tuple[idx];
  }
  return out;
};

export const REMAINING_TRANSLATIONS_B = {
  tr: buildLang(0),
  en: buildLang(1),
  de: buildLang(2),
  es: buildLang(3),
  fr: buildLang(4),
};
